  void Update(){if(!canvas)return;if(Screen.width!=oldWidth||Screen.height!=oldHeight){Build();return;}if(!scene.Ready||busy)return;if(EventSystem.current&&EventSystem.current.currentSelectedGameObject?.GetComponent<TMP_InputField>()?.isFocused==true)return;float left=panel.sizeDelta.x;if(Input.mousePosition.x<left)return;bool changed=false;float fine=Input.GetKey(KeyCode.LeftControl)?.2f:Input.GetKey(KeyCode.LeftShift)?3:1;float dt=Time.unscaledDeltaTime*fine;var p=(Vector2)Input.mousePosition;if(Input.GetMouseButtonDown(1)||Input.GetMouseButtonDown(2))last=p;if(Input.GetMouseButton(1)){draft.Yaw+= (p.x-last.x)*.35f;changed=true;}if(Input.GetMouseButton(2)){draft.OffsetX+=(p.x-last.x)*.001f;draft.OffsetY+=(p.y-last.y)*.001f;changed=true;}last=p;float wheel=Input.mouseScrollDelta.y;if(wheel!=0){draft.Scale=Mathf.Clamp(draft.Scale*(1+wheel*.06f*fine),.1f,5);changed=true;}float x=(Input.GetKey(KeyCode.RightArrow)?1:0)-(Input.GetKey(KeyCode.LeftArrow)?1:0),y=(Input.GetKey(KeyCode.UpArrow)?1:0)-(Input.GetKey(KeyCode.DownArrow)?1:0),z=(Input.GetKey(KeyCode.E)?1:0)-(Input.GetKey(KeyCode.Q)?1:0);if(x!=0||y!=0||z!=0){draft.OffsetX+=x*dt*.15f;draft.OffsetY+=y*dt*.15f;draft.OffsetZ+=z*dt*.15f;changed=true;}if(changed){draft.OffsetX=Mathf.Clamp(draft.OffsetX,-2,2);draft.OffsetY=Mathf.Clamp(draft.OffsetY,-1,1);draft.OffsetZ=Mathf.Clamp(draft.OffsetZ,-.2f,5);draft.Yaw=Mathf.Repeat(draft.Yaw+180,360)-180;Apply();}}
